1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <style>
11	    :root {
12	      --circle-hue: #8ec5ff;
13	      --circle-core: #4a7dd9;
14	      --circle-shadow: #1f3a75;
15	      --cycle: 2.5s;
16	    }
17	    * {
18	      margin: 0;
19	      padding: 0;
20	      box-sizing: border-box;
21	    }
22	    body {
23	      width: 100vw;
24	      height: 100vh;
25	      height: 100dvh;
26	      display: flex;
27	      flex-direction: column;
28	      justify-content: center;
29	      align-items: center;
30	      gap: 24px;
31	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
32	      overflow: hidden;
33	    }
34	    svg {
35	      width: min(400px, 80vmin);
36	      height: min(400px, 80vmin);
37	      overflow: visible;
38	      cursor: pointer;
39	      user-select: none;
40	      -webkit-tap-highlight-color: transparent;
41	      transition: filter 0.3s ease;
42	    }
43	    .circle-btn:hover svg {
44	      filter: brightness(1.08);
45	    }
46	    .ambient {
47	      fill: var(--circle-hue);
48	      opacity: 0.12;
49	      filter: blur(30px);
50	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
51	      transform-origin: 200px 200px;
52	      will-change: transform, opacity;
53	    }
54	    .core {
55	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
56	      transform-origin: 200px 200px;
57	      filter: url(#glow);
58	      will-change: transform, opacity;
59	    }
60	    .highlight {
61	      fill: url(#highlightGradient);
62	      transform-origin: 200px 200px;
63	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
64	      pointer-events: none;
65	      will-change: transform, opacity;
66	    }
67	    .ring {
68	      fill: none;
69	      stroke: var(--circle-hue);
70	      stroke-width: 2.5;
71	      transform-origin: 200px 200px;
72	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
73	      will-change: transform, opacity, stroke-width;
74	    }
75	    .ring--delay-1 {
76	      animation-delay: calc(var(--cycle) / 3);
77	    }
78	    .ring--delay-2 {
79	      animation-delay: calc(var(--cycle) / 3 * 2);
80	    }
81	    @keyframes pulse {
82	      0%, 100% {
83	        transform: scale(1);
84	        opacity: 0.9;
85	      }
86	      50% {
87	        transform: scale(1.05);
88	        opacity: 1;
89	      }
90	    }
91	    @keyframes breathe {
92	      0%, 100% {
93	        transform: scale(0.95);
94	        opacity: 0.1;
95	      }
96	      50% {
97	        transform: scale(1.1);
98	        opacity: 0.18;
99	      }
100	    }
101	    @keyframes ripple {
102	      0% {
103	        transform: scale(1);
104	        opacity: 0.6;
105	        stroke-width: 2.5;
106	      }
107	      100% {
108	        transform: scale(1.35);
109	        opacity: 0;
110	        stroke-width: 0.5;
111	      }
112	    }
113	    body.paused .core,
114	    body.paused .ring,
115	    body.paused .ambient,
116	    body.paused .highlight {
117	      animation-play-state: paused;
118	    }
119	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
120	       once JS is ready, control defers entirely to body.paused so the user
121	       can still explicitly resume even with reduced motion preferred. */
122	    @media (prefers-reduced-motion: reduce) {
123	      body:not(.js-ready) .core,
124	      body:not(.js-ready) .ring,
125	      body:not(.js-ready) .ambient,
126	      body:not(.js-ready) .highlight {
127	        animation-play-state: paused;
128	      }
129	    }
130	    .speed-label {
131	      color: var(--circle-hue);
132	      font-family: system-ui, sans-serif;
133	      font-size: 0.85rem;
134	      letter-spacing: 0.05em;
135	      opacity: 0.85;
136	      user-select: none;
137	      text-align: center;
138	    }
139	    .hint {
140	      display: block;
141	      margin-top: 4px;
142	      font-size: 0.7rem;
143	      opacity: 0.85;
144	    }
145	    .controls {
146	      display: flex;
147	      align-items: center;
148	      gap: 12px;
149	      max-width: min(320px, 90vw);
150	    }
151	    .pause-btn {
152	      display: inline-flex;
153	      align-items: center;
154	      justify-content: center;
155	      width: 36px;
156	      height: 36px;
157	      padding: 0;
158	      border-radius: 50%;
159	      border: 1px solid var(--circle-hue);
160	      background: transparent;
161	      color: var(--circle-hue);
162	      cursor: pointer;
163	      transition: background 0.2s ease;
164	    }
165	    .pause-btn:hover {
166	      background: rgba(142, 197, 255, 0.15);
167	    }
168	    .pause-btn:focus-visible {
169	      outline: 2px solid var(--circle-hue);
170	      outline-offset: 2px;
171	    }
172	    @media (prefers-contrast: more) {
173	      .pause-btn {
174	        border-width: 2px;
175	      }
176	      .ring {
177	        stroke-width: 3.5;
178	      }
179	    }
180	    .pause-btn svg {
181	      width: 14px;
182	      height: 14px;
183	    }
184	    .circle-btn {
185	      display: inline-flex;
186	      padding: 0;
187	      border: none;
188	      background: none;
189	      cursor: pointer;
190	      -webkit-tap-highlight-color: transparent;
191	      border-radius: 50%;
192	    }
193	    .circle-btn:focus-visible svg {
194	      outline: 2px solid var(--circle-hue);
195	      outline-offset: 8px;
196	      border-radius: 50%;
197	    }
198	  </style>
199	</head>
200	<body>
201	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation. Click to change pulse speed." aria-describedby="speedText">
202	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
203	    <defs>
204	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
205	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
206	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
207	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
208	      </radialGradient>
209	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
210	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
211	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
212	      </radialGradient>
213	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
214	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
215	        <feColorMatrix in="blur" type="matrix"
216	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
217	        <feMerge>
218	          <feMergeNode in="tintedBlur"/>
219	          <feMergeNode in="SourceGraphic"/>
220	        </feMerge>
221	      </filter>
222	    </defs>
223	    <circle class="ambient" cx="200" cy="200" r="160"/>
224	    <circle class="ring" cx="200" cy="200" r="140"/>
225	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
226	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
227	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
228	    <circle class="highlight" cx="200" cy="200" r="140"/>
229	  </svg>
230	  </button>
231	  <div class="controls">
232	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
233	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
234	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
235	      </svg>
236	    </button>
237	    <p class="speed-label" id="speedLabel">
238	      <span id="speedText" aria-live="polite">Normal speed</span>
239	      <span class="hint" aria-hidden="true">Click circle to change speed</span>
240	    </p>
241	  </div>
242	  <script>
243	    const circleBtn = document.getElementById('circleBtn');
244	    const speedText = document.getElementById('speedText');
245	    const pauseBtn = document.getElementById('pauseBtn');
246	    const pauseIcon = document.getElementById('pauseIcon');
247	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
248	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
249	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
250	    const speeds = [
251	      { value: '2.5s', name: 'Normal speed' },
252	      { value: '1.2s', name: 'Fast speed' },
253	      { value: '4.5s', name: 'Slow speed' },
254	    ];
255	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
256	    let speedIndex = 0;
257	    let manuallyPaused = reducedMotionQuery.matches;
258	    // Once the user has explicitly toggled pause/play, respect that choice
259	    // instead of letting a later OS-level reduced-motion change override it.
260	    let userHasChosen = false;
261	
262	    const STORAGE_KEY = 'pulsing-circle-prefs';
263	    try {
264	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
265	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
266	        speedIndex = saved.speedIndex;
267	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
268	      }
269	      if (saved && typeof saved.manuallyPaused === 'boolean') {
270	        manuallyPaused = saved.manuallyPaused;
271	        userHasChosen = true;
272	      }
273	    } catch {
274	      // Ignore malformed or inaccessible storage; fall back to defaults.
275	    }
276	
277	    function savePrefs() {
278	      try {
279	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
280	      } catch {
281	        // Storage may be unavailable (e.g. private browsing); ignore.
282	      }
283	    }
284	
285	    function updateLabels() {
286	      const { name } = speeds[speedIndex];
287	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
288	    }
289	
290	    function cycleSpeed() {
291	      speedIndex = (speedIndex + 1) % speeds.length;
292	      const { value } = speeds[speedIndex];
293	      circleBtn.style.setProperty('--cycle', value);
294	      // Restart animations from the beginning so the new speed feels immediate
295	      // instead of jumping mid-cycle.
296	      animatedEls.forEach((el) => {
297	        el.style.animation = 'none';
298	        void el.offsetWidth;
299	        el.style.animation = '';
300	      });
301	      updateLabels();
302	      savePrefs();
303	    }
304	
305	    function applyPauseState() {
306	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
307	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
308	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
309	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
310	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
311	      updateLabels();
312	    }
313	
314	    function togglePause() {
315	      manuallyPaused = !manuallyPaused;
316	      userHasChosen = true;
317	      applyPauseState();
318	      savePrefs();
319	    }
320	
321	    circleBtn.addEventListener('click', cycleSpeed);
322	    pauseBtn.addEventListener('click', togglePause);
323	
324	    document.addEventListener('visibilitychange', applyPauseState);
325	
326	    reducedMotionQuery.addEventListener('change', (e) => {
327	      if (userHasChosen) return;
328	      manuallyPaused = e.matches;
329	      applyPauseState();
330	    });
331	
332	    // Keep multiple open tabs/windows of this page in sync with each other.
333	    window.addEventListener('storage', (e) => {
334	      if (e.key !== STORAGE_KEY || !e.newValue) return;
335	      try {
336	        const saved = JSON.parse(e.newValue);
337	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
338	          speedIndex = saved.speedIndex;
339	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
340	        }
341	        if (typeof saved.manuallyPaused === 'boolean') {
342	          manuallyPaused = saved.manuallyPaused;
343	          userHasChosen = true;
344	        }
345	        applyPauseState();
346	      } catch {
347	        // Ignore malformed storage updates from other tabs.
348	      }
349	    });
350	
351	    applyPauseState();
352	    updateLabels();
353	    document.body.classList.add('js-ready');
354	  </script>
355	</body>
356	</html>
